  const [filters, setFilters] = useState(draftFilters); const [deleteTarget, setDeleteTarget] = useState(null); const [notice, setNotice] = useState(location.state?.message || '');
  const params = { page, size, sort, ...Object.fromEntries(Object.entries(filters).map(([key, value]) => [key, value || undefined])) };
