  const removeMutation = useMutation({ mutationFn: billsApi.remove, onSuccess: () => { setDeleteTarget(null); setNotice('Bill deleted successfully.'); queryClient.invalidateQueries({ queryKey: ['bills'] }); queryClient.invalidateQueries({ queryKey: ['bill-summary'] }); } });
