  const [form, setForm] = useState({ ...EMPTY_FORM, items: [EMPTY_ITEM()] }); const [notice, setNotice] = useState(location.state?.message || ''); const [errors, setErrors] = useState({}); const [attachmentUploading, setAttachmentUploading] = useState(false);
